// Keep only what the AI needs: sender, subject and the new text (quoted history and signatures cut).
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const sender = (m.from && m.from.value && m.from.value[0]) || {};
  let body = m.text || '';
  if (!body && m.html) body = m.html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
  const cut = body.search(/\n(On .{5,200}wrote:|-{2,} ?Original Message|From: .+\nSent: )/i);
  if (cut > 0) body = body.slice(0, cut);
  body = body.split('\n').filter(l => !l.trim().startsWith('>')).join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, 4000);
  const fromEmail = (sender.address || '').toLowerCase();
  out.push({ json: {
    id: m.id, threadId: m.threadId, date: m.date || '',
    fromName: sender.name || '', fromEmail,
    noReplySender: /no-?reply|do-?not-?reply|mailer-daemon|notifications?@/.test(fromEmail),
    subject: m.subject || '(no subject)', body: body || '(empty email)',
  }});
}
return out;

