// Join the AI's verdict to each email and find the Gmail label "AI/<Category>" (create them once with the setup branch).
const labels = {};
for (const l of $input.all()) labels[l.json.name] = l.json.id;
return $('Clean email').all().map((e, i) => {
  const ai = $('Sort and draft').all()[i].json.output || {};
  const category = ai.category || 'other';
  const labelName = 'AI/' + category.charAt(0).toUpperCase() + category.slice(1);
  const needsReply = !!ai.needs_reply && !e.json.noReplySender && !!(ai.reply || '').trim();
  const subject = e.json.subject;
  return { json: {
    ...e.json, category, priority: ai.priority || 'normal', summary: ai.summary || '',
    needsReply, reply: (ai.reply || '').trim(),
    replySubject: /^re:/i.test(subject) ? subject : 'Re: ' + subject,
    labelName, labelId: labels[labelName] || null,
  }};
});

// Keep a short log for the evening summary (static data is saved in production runs only),
// and prepare the Telegram alert for leads, clients and anything high priority.
const e = { ...$('Attach label').item.json };
const draftFailed = e.needsReply && !!$input.item.json.error;
if (draftFailed) e.needsReply = false;
const store = $getWorkflowStaticData('global');
store.today = (store.today || []).concat([{ at: new Date().toISOString(), from: e.fromName || e.fromEmail,
  subject: e.subject, category: e.category, priority: e.priority, summary: e.summary, drafted: e.needsReply }]).slice(-300);
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const icon = { lead: '🔥', client: '🤝', support: '🛟', invoice: '🧾', personal: '👋' }[e.category] || '📩';
const alert = e.category === 'lead' || e.category === 'client' || e.priority === 'high';
const text = `${icon} <b>${esc(e.category.toUpperCase())}</b> · ${esc(e.priority)} priority\n` +
  `👤 ${esc(e.fromName || e.fromEmail)}\n✉️ ${esc(e.subject)}\n\n${esc(e.summary)}` +
  (e.needsReply ? `\n\n✍️ Reply draft is waiting in Gmail:\n<i>${esc(e.reply.slice(0, 600))}</i>` : '') +
  (draftFailed ? '\n\n⚠️ The reply draft could not be created in Gmail.' : '');
return { json: { alert, text } };

// Evening summary of everything sorted since the last one, then start a new list.
const store = $getWorkflowStaticData('global');
const items = store.today || [];
store.today = [];
if (!items.length) return [];
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const counts = {};
for (const it of items) counts[it.category] = (counts[it.category] || 0) + 1;
const order = ['lead', 'client', 'support', 'invoice', 'personal', 'other', 'newsletter', 'spam'];
const line = order.filter(c => counts[c]).map(c => `${c} ${counts[c]}`).join(' · ');
const important = items.filter(it => ['lead', 'client', 'support'].includes(it.category) || it.priority === 'high');
const drafts = items.filter(it => it.drafted).length;
let text = `📬 <b>Inbox summary</b>: ${items.length} emails\n${line}\n✍️ ${drafts} reply drafts waiting in Gmail`;
if (important.length) text += '\n\n<b>Needs you:</b>\n' + important.slice(0, 10).map(it => `• ${esc(it.from)}: ${esc(it.summary)}`).join('\n');
return [{ json: { text } }];
